#include <stdio.h>
#include <stdlib.h>
struct Elem { int val; int cnt; };
int cmp(const void *a, const void *b) { return ((struct Elem*)b)->cnt - ((struct Elem*)a)->cnt; }
int cmp_val(const void *a, const void *b) { return (*(int*)a - *(int*)b); }
int main() {
    int n; if (scanf("%d", &n) != 1) return 0;
    int *a = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &a[i]);
    int k; scanf("%d", &k);
    qsort(a, n, sizeof(int), cmp_val);
    struct Elem elems[10000]; int u = 0;
    for (int i = 0; i < n;) {
        int v = a[i], c = 0;
        while (i < n && a[i] == v) { c++; i++; }
        elems[u].val = v; elems[u].cnt = c; u++;
    }
    qsort(elems, u, sizeof(struct Elem), cmp);
    for (int i = 0; i < k && i < u; i++) {
        if (i > 0) putchar(' ');
        printf("%d", elems[i].val);
    }
    putchar('\n');
    free(a);
    return 0;
}

