#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>
using namespace std;
int main() {
    int n; if (cin >> n) {
        unordered_map<int, int> cnt;
        for (int i = 0; i < n; i++) { int x; cin >> x; cnt[x]++; }
        int k; cin >> k;
        vector<pair<int, int>> v;
        for (auto &p : cnt) v.push_back({p.second, p.first});
        sort(v.rbegin(), v.rend());
        for (int i = 0; i < k; i++) {
            if (i > 0) cout << " ";
            cout << v[i].second;
        }
        cout << "\n";
    }
    return 0;
}

code.Java:
import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextInt()) {
            int n = sc.nextInt();
            HashMap<Integer, Integer> cnt = new HashMap<>();
            for (int i = 0; i < n; i++) { int x = sc.nextInt(); cnt.put(x, cnt.getOrDefault(x, 0) + 1); }
            int k = sc.nextInt();
            List<Integer> list = new ArrayList<>(cnt.keySet());
            list.sort((a, b) -> cnt.get(b) - cnt.get(a));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < k && i < list.size(); i++) {
                if (i > 0) sb.append(" ");
                sb.append(list.get(i));
            }
            System.out.println(sb.toString());
        }
    }
}

