const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0];
        const arr = toks.slice(1, 1 + n);
        const k = toks[1 + n];
        const cnt = {};
        for (const x of arr) cnt[x] = (cnt[x] || 0) + 1;
        const sorted = Object.keys(cnt).map(Number).sort((a, b) => cnt[b] - cnt[a]);
        console.log(sorted.slice(0, k).join(" "));
    }
}
main();

